theorem chow_cycleClass_divCycle {X : Scheme.{u}}
    [AlgebraicGeometry.IsNoetherian X] {p : ℕ∞}
    {w : X} {f : X.residueField w} (hf : f ≠ 0)
    (hw : Scheme.codim w + 1 = p)
    (hmem : Scheme.divCycle w f hf ∈ Scheme.cyclesOfCodim X p) :
    Scheme.cycleClass X p ⟨Scheme.divCycle w f hf, hmem⟩ = 0

theorem subsingleton_hPrimeOne_affine {V : Scheme.Opens p1}
