lemma support_div {w : X} {f : X.residueField w} (hf : f ≠ 0)
    (hfin : (Function.support (divFun w f)).Finite) :
    Function.support ⇑(div w f hfin) = {x | ∃ h : x ⋖ w, ordAt h f ≠ 1}

lemma support_div_subset (w : X) (f : X.residueField w)
    (hfin : (Function.support (divFun w f)).Finite) :
    Function.support ⇑(div w f hfin) ⊆ {x | x ⋖ w}

theorem freeYonedaHomOfSection_comp {P P' : Cᵒᵖ ⥤ AddCommGrpCat.{u}}
