    {x : ℂ ⊗[ℚ] (V ⊗[ℚ] W)} (hx : x ∈ slotModule h k s) :
    sigmaQ (V ⊗[ℚ] W) x ∈ slotModule h k (slotSwap s)

private theorem slotModule_repr {h : QHodgeStructure n V}
    {k : QHodgeStructure m W} {ab cd : ℤ × ℤ} {D : ℕ}
    (e : Fin D → ↥(h.H ab))
    (hspan : ∀ y : ↥(h.H ab), ∃ c : Fin D → ℂ, (∑ i, c i • e i) = y)
    {u : (ℂ ⊗[ℚ] V) ⊗[ℂ] (ℂ ⊗[ℚ] W)}
    (hu : u ∈ LinearMap.range (TensorProduct.mapIncl (h.H ab) (k.H cd))) :
    ∃ w : Fin D → ℂ ⊗[ℚ] W, (∀ i, w i ∈ k.H cd)
