    y ∈ nvChartOpen c (1 : Sec (cRingHom sX) W)

theorem mem_imageOpen_of_nvChartOpen_one {c : GluedChart sX d} {W : X.Opens}
    {y : Fin d → ℂ} (hy : y ∈ nvChartOpen c (1 : Sec (cRingHom sX) W)) :
    y ∈ imageOpen c ((Opens.map (sPointsToZariski sX)).obj W)

theorem chartGradOpen_res_le (c : GluedChart sX d) {V W : X.Opens}
    (hVW : V ≤ W) (b : Sec (cRingHom sX) W) {y : Fin d → ℂ}
    (hyt : y ∈ c.1.target) (hm : toSpace sX (c.1.symm y) ∈ V) :
    chartGradOpen c (res (cRingHom sX) hVW b) y = chartGradOpen c b y

theorem _root_.DirectSum.IsInternal.regroup {A : κ → Submodule R M}
    [DecidableEq ι] [DecidableEq κ] (hA : DirectSum.IsInternal A) (f : κ → ι) :
