theorem freeYonedaHomOfSection_comp {P Q : Cᵒᵖ ⥤ AddCommGrpCat.{u}}
    (γ : P ⟶ Q) {U : C} (s : P.obj (op U)) :
    freeYonedaHomOfSection s ≫ γ = freeYonedaHomOfSection (γ.app (op U) s)

theorem exists_rep (hV : IsAffineOpen V) {g : Γ(p1, V)} {W : Scheme.Opens p1}
    (hW : W = p1.basicOpen g) (hWV : W ≤ V) (z : Γ(p1, W)) :
    ∃ (a : Γ(p1, V)) (m : ℕ), z * rmap hWV (g ^ m) = rmap hWV a

theorem exists_clear (hV : IsAffineOpen V) {g : Γ(p1, V)} {W : Scheme.Opens p1}
    (hW : W = p1.basicOpen g) (hWV : W ≤ V) (a : Γ(p1, V)) (h : rmap hWV a = 0) :
    ∃ m : ℕ, g ^ m * a = 0

theorem preRealize_eq_zero_of_mem_relSet {p : ℕ} {w : DRFree (Poly N) p}
    (hw : w ∈ relSet ℂ (Poly N) p) :
